def _review_info_domain(col: str) -> str | None:
    if col in {
        HCR_CATEGORY_COL,
        KTP_ECONOMIES_COL,
        KTP_ECONOMY_MATCH_COL,
        KTP_HCR_PRIMARY_AFFILIATIONS_COL,
