    }:
        return REVIEW_DOMAIN_XLSX
    if col in {
        SSNAD_DISPLAY_NAME_COL,
        SSNAD_DISPLAY_NAME_ALTERNATIVES_COL,
        KTP_SSN_FIELD_DISPLAY_NAMES_LIST_COL,
        KTP_SSN_TOP_INSTITUTIONS_COL,
