from __future__ import annotations

import json
import re
from collections import defaultdict

import duckdb

SRC_TOK = 'ktp.source_key_first_name_norm_tok'
SRC_LAST = 'ktp.source_key_last_name_norm'
XLSX_TOK = 'ktp.first_name_norm_tok'
XLSX_LAST = 'ktp.last_name_norm'

def present(v):
    return isinstance(v, str) and bool(v.strip())

def clean_name_token(token):
    return re.sub(r'[^0-9a-z]+', '', str(token).strip().lower())

def clean_tokens(tokens):
    if not isinstance(tokens, list):
        return []
    out = []
    for token in tokens:
        cleaned = clean_name_token(token)
        if cleaned:
            out.append(cleaned)
    return out

def expand_nonfirst_compact_initials(tokens):
    out = []
    for i, token in enumerate(tokens):
        if i > 0 and token.isalpha() and 1 < len(token) <= 3:
            out.extend(token)
        else:
            out.append(token)
    return out

def relaxed_exact(v):
    if not present(v):
        return True
    try:
        p = json.loads(v)
    except json.JSONDecodeError:
        return False
    if not isinstance(p, dict):
        return False
    sk_last = clean_name_token(p.get(SRC_LAST) or '')
    xl_last = clean_name_token(p.get(XLSX_LAST) or '')
    sk = clean_tokens(p.get(SRC_TOK, []))
    xl = clean_tokens(p.get(XLSX_TOK, []))
    if not sk or not sk_last or not xl_last or sk_last != xl_last:
        return False
    if sorted(sk) == sorted(xl):
        return True
    return sorted(expand_nonfirst_compact_initials(sk)) == sorted(expand_nonfirst_compact_initials(xl))

